          .onComplete(
              ar -> {
                if (ar.succeeded()) {
                  this.config = new ServerConfig(ar.result());
                  trySetupServer(startPromise);
                } else {
                  startPromise.fail(ar.cause());
                }
              });
    } else {
      // Config already provided, proceed with setup
      trySetupServer(startPromise);
