package com.datasqrl.graphql;

import graphql.schema.DataFetcher;
import graphql.schema.DataFetchingEnvironment;
import io.vertx.core.Promise;

public final class VertxDataFetcher {

  private VertxDataFetcher() {}

  public static <T> DataFetcher<Object> create(Handler<T> handler) {
    return env -> {
      Promise<T> promise = Promise.promise();
      handler.handle(env, promise);
      return promise.future().toCompletionStage();
    };
  }

  @FunctionalInterface
  public interface Handler<T> {
    void handle(DataFetchingEnvironment environment, Promise<T> promise);
  }
}
